// Gate test G16: the module stands alone, and its core is pure.
// - Nothing under module/ imports from outside module/.
// - Files under module/core/ import only other files under module/core/, and touch no browser globals.
// - Files under shell/ reach the module only through module/index.ts (and its stylesheets).
// Do not edit this file.
import { expect, test } from 'vitest';
import { existsSync, readFileSync, readdirSync, statSync } from 'node:fs';
import { dirname, join, relative, resolve, sep } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = fileURLToPath(new URL('../../', import.meta.url));
const SOURCE = /\.(ts|js|mjs|svelte)$/;

function walk(dir: string): string[] {
  if (!existsSync(dir)) return [];
  return readdirSync(dir).flatMap((name) => {
    const p = join(dir, name);
    return statSync(p).isDirectory() ? walk(p) : SOURCE.test(p) ? [p] : [];
  });
}
function specifiers(file: string): string[] {
  const text = readFileSync(file, 'utf8');
  const found: string[] = [];
  const patterns = [
    /^\s*import\s+(?:type\s+)?[^'";]*?\sfrom\s*['"]([^'"]+)['"]/gm, // import x from '...'
    /^\s*export\s+(?:type\s+)?[^'";]*?\sfrom\s*['"]([^'"]+)['"]/gm, // export x from '...'
    /^\s*import\s*['"]([^'"]+)['"]/gm, // import '...'
    /\bimport\s*\(\s*['"]([^'"]+)['"]\s*\)/g, // import('...')
    /new\s+URL\s*\(\s*['"]([^'"]+)['"]\s*,\s*import\.meta\.url/g, // new URL('...', import.meta.url)
  ];
  for (const re of patterns) for (const m of text.matchAll(re)) found.push(m[1]);
  return found;
}
const rel = (p: string) => relative(ROOT, p).split(sep).join('/');

test('G16 the module exists, with its entry point and its core', () => {
  expect(existsSync(join(ROOT, 'module/index.ts'))).toBe(true);
  expect(existsSync(join(ROOT, 'module/core/index.ts'))).toBe(true);
});

test('G16 nothing under module/ imports from outside module/', () => {
  for (const file of walk(join(ROOT, 'module'))) {
    for (const s of specifiers(file)) {
      if (!s.startsWith('.')) continue;
      const target = rel(resolve(dirname(file), s));
      expect(target.startsWith('module/'), `${rel(file)} imports ${s}`).toBe(true);
    }
  }
});

test('G16 the core imports only the core and uses no browser globals', () => {
  for (const file of walk(join(ROOT, 'module/core'))) {
    const text = readFileSync(file, 'utf8');
    for (const s of specifiers(file)) {
      const target = s.startsWith('.') ? rel(resolve(dirname(file), s)) : s;
      expect(target.startsWith('module/core/'), `${rel(file)} imports ${s}`).toBe(true);
    }
    const code = text.replace(/\/\*[\s\S]*?\*\//g, '').replace(/\/\/.*$/gm, '');
    expect(/\b(window|document|navigator|localStorage|sessionStorage)\b/.test(code), `${rel(file)} uses a browser global`).toBe(false);
  }
});

test('G16 the shell reaches the module only through module/index.ts', () => {
  for (const file of walk(join(ROOT, 'shell'))) {
    for (const s of specifiers(file)) {
      if (!s.startsWith('.')) continue;
      const target = rel(resolve(dirname(file), s));
      if (!target.startsWith('module/')) continue;
      const ok = /^module\/index(\.ts)?$/.test(target) || /^module\/.*\.css$/.test(target);
      expect(ok, `${rel(file)} imports ${s}`).toBe(true);
    }
  }
});
